{"command":"python3 <<'PY'
# Debug our encryption: compare with Python's expected crc function
import binascii
# Python's crc32(ch, crc) = (crc>>8) ^ table[(crc ^ ch) &0xff]
# binascii.crc32(bytes([ch]), crc) should be same? Let's test
def gen_crc(crc):
    for _ in range(8):
        if crc & 1:
            crc = (crc >> 1) ^ 0xedb88320
        else:
            crc >>= 1
    return crc & 0xffffffff

table = list(map(gen_crc, range(256)))
def crc32_py(ch, crc):
    return (crc >> 8) ^ table[(crc ^ ch) & 0xFF]

for crc in [0, 305419896, 12345]:
    for ch in [0, 65, 97, 255]:
        a = crc32_py(ch, crc) & 0xffffffff
        b = binascii.crc32(bytes([ch]), crc) & 0xffffffff
        if a!=b:
            print(f"mismatch crc={crc} ch={ch} py={a:#x} bin={b:#x}")
        else:
            print(f"ok {crc},{ch} => {a:#x}")
PY"}

