            w[i] = ((chunk[i*4] as u32) << 24) | ((chunk[i*4+1] as u32) << 16) | ((chunk[i*4+2] as u32) << 8) | (chunk[i*4+3] as u32);
        }
        for i in 16..80 {
            w[i] = (w[i-3] ^ w[i-8] ^ w[i-14] ^ w[i-16]).rotate_left(1);
        }
        let mut a = h0;
        let mut b = h1;
        let mut c = h2;
        let mut d = h3;
        let mut e = h4;
        for i in 0..80 {
            let (f, k) = if i < 20 {
                ((b & c) | ((!b) & d), 0x5A827999u32)
            } else if i < 40 {
                (b ^ c ^ d, 0x6ED9EBA1u32)
            } else if i < 60 {
                ((b & c) | (b & d) | (c & d), 0x8F1BBCDCu32)
            } else {
                (b ^ c ^ d, 0xCA62C1D6u32)
            };
            let temp = a.rotate_left(5).wrapping_add(f).wrapping_add(e).wrapping_add(k).wrapping_add(w[i]);
            e = d;
            d = c;
            c = b.rotate_left(30);
            b = a;
            a = temp;
        }
        h0 = h0.wrapping_add(a);
        h1 = h1.wrapping_add(b);
        h2 = h2.wrapping_add(c);
        h3 = h3.wrapping_add(d);
        h4 = h4.wrapping_add(e);
    }
    let mut out = [0u8; 20];
    out[0..4].copy_from_slice(&h0.to_be_bytes());
    out[4..8].copy_from_slice(&h1.to_be_bytes());
    out[8..12].copy_from_slice(&h2.to_be_bytes());
    out[12..16].copy_from_slice(&h3.to_be_bytes());
    out[16..20].copy_from_slice(&h4.to_be_bytes());
    out
}

pub fn hmac_sha1(key: &[u8], msg: &[u8]) -> [u8; 20] {
    let mut k = [0u8; 64];
    if key.len() > 64 {
        let h = sha1(key);
        k[0..20].copy_from_slice(&h);
    } else {
        k[0..key.len()].copy_from_slice(key);
    }
    let mut ipad = [0x36u8; 64];
    let mut opad = [0x5cu8; 64];
    for i in 0..64 {
        ipad[i] ^= k[i];
        opad[i] ^= k[i];
    }
    let mut inner = Vec::with_capacity(64 + msg.len());
    inner.extend_from_slice(&ipad);
    inner.extend_from_slice(msg);
    let inner_hash = sha1(&inner);
    let mut outer = Vec::with_capacity(64 + 20);
    outer.extend_from_slice(&opad);
    outer.extend_from_slice(&inner_hash);
    sha1(&outer)
}

pub fn pbkdf2_hmac_sha1(password: &[u8], salt: &[u8], iter: u32, dklen: usize) -> Vec<u8> {
    let hlen = 20;
    let l = (dklen + hlen - 1) / hlen;
    let mut dk = Vec::new();
    for i in 1..=l {
        let mut block = Vec::from(salt);
        block.extend_from_slice(&(i as u32).to_be_bytes());
        let mut u = hmac_sha1(password, &block);
        let mut t = u;
        for _ in 1..iter {
            u = hmac_sha1(password, &u);
            for j in 0..hlen {
                t[j] ^= u[j];
            }
        }
        dk.extend_from_slice(&t);
    }
    dk.truncate(dklen);
    dk
}

// ZipCrypto
fn crc32_update(crc: u32, b: u8, table: &[u32; 256]) -> u32 {
    (crc >> 8) ^ table[((crc ^ (b as u32)) & 0xFF) as usize]
}

fn make_crc_table() -> [u32; 256] {
    let mut table = [0u32; 256];
    for i in 0..256 {
        let mut c = i as u32;
        for _ in 0..8 {
            if c & 1 != 0 {
                c = 0xEDB88320 ^ (c >> 1);
            } else {
                c >>= 1;
            }
        }
        table[i] = c;
    }
    table
}

pub fn zipcrypto_check(password: &[u8], header_enc: &[u8], check_byte: u8) -> Option<[u32; 3]> {
    let table = make_crc_table();
    let mut k0: u32 = 305419896;
    let mut k1: u32 = 591751049;
    let mut k2: u32 = 878082192;
    for &b in password {
        k0 = crc32_update(k0, b, &table);
        k1 = k1.wrapping_add(k0 & 0xFF).wrapping_mul(134775813).wrapping_add(1);
        k2 = crc32_update(k2, (k1 >> 24) as u8, &table);
    }
    // decrypt header
    let mut keys = [k0, k1, k2];
    let mut last_plain: u8 = 0;
    for (i, &c) in header_enc.iter().enumerate() {
        let temp = (keys[2] | 2).wrapping_mul((keys[2] | 2) ^ 1) >> 8;
        let t = (temp & 0xFF) as u8;
        let p = c ^ t;
        // update
        keys[0] = crc32_update(keys[0], p, &table);
        keys[1] = keys[1].wrapping_add(keys[0] & 0xFF).wrapping_mul(134775813).wrapping_add(1);
        keys[2] = crc32_update(keys[2], (keys[1] >> 24) as u8, &table);
        if i == 11 {
            last_plain = p;
        }
    }
    if last_plain != check_byte {
        return None;
    }
    Some(keys)
}

pub fn zipcrypto_decrypt(keys: &mut [u32; 3], data: &[u8]) -> Vec<u8> {
    let table = make_crc_table();
    let mut out = Vec::with_capacity(data.len());
    for &c in data {
        let temp = (keys[2] | 2).wrapping_mul((keys[2] | 2) ^ 1) >> 8;
        let t = (temp & 0xFF) as u8;
        let p = c ^ t;
        out.push(p);
        keys[0] = crc32_update(keys[0], p, &table);
        keys[1] = keys[1].wrapping_add(keys[0] & 0xFF).wrapping_mul(134775813).wrapping_add(1);
        keys[2] = crc32_update(keys[2], (keys[1] >> 24) as u8, &table);
    }
    out
}
