        }
    }
    let fname_str = String::from_utf8_lossy(&e.fname).to_string();
    Ok(ZipFileData {
        file_name: fname_str,
        flag: e.flag,
        method: e.method,
        crc: e.crc,
        comp_size: e.comp_size,
        uncomp_size: e.uncomp_size,
        mod_time: e.mod_time,
        aes_extra,
        file_data,
    })
