fn expand_charset(code: &str) -> Vec<char> {
    let mut v: Vec<char> = Vec::new();
    for c in code.chars() {
        match c {
            'l' => { for ch in 'a'..='z' { v.push(ch); } },
            'u' => { for ch in 'A'..='Z' { v.push(ch); } },
            'd' => { for ch in '0'..='9' { v.push(ch); } },
            'h' => { for ch in '0'..='9' { v.push(ch); } for ch in 'a'..='f' { v.push(ch); } },
            'H' => { for ch in '0'..='9' { v.push(ch); } for ch in 'A'..='F' { v.push(ch); } },
            's' => {
                v.push(' ');
                for code in 33u8..=47u8 { v.push(code as char); }
                for code in 58u8..=64u8 { v.push(code as char); }
                for code in 91u8..=96u8 { v.push(code as char); }
                for code in 123u8..=126u8 { v.push(code as char); }
            },
            _ => {},
        }
    }
    v.sort();
    v.dedup();
    v
}

fn format_elapsed(start: Instant) -> String {
    let d = start.elapsed();
    let secs = d.as_secs();
    let millis = d.subsec_millis();
    let micros = (d.subsec_nanos() / 1000) % 1000;
    let nanos = d.subsec_nanos() % 1000;
    if secs > 0 {
        format!("Time elapsed: {}s {}ms {}us {}ns", secs, millis, micros, nanos)
    } else if millis > 0 {
        format!("Time elapsed: {}ms {}us {}ns", millis, micros, nanos)
    } else if d.subsec_micros() > 0 {
        // micros is subsec_micros %1000? For 210us, subsec_micros=210, micros=210, nanos=890. Good.
        // But need full micros? For 210us, micros=210. Good. For 1500us (1.5ms), millis=1, micros=500. Good.
        // Here millis==0, so subsec_micros <1000, micros==subsec_micros. Good.
        format!("Time elapsed: {}us {}ns", d.subsec_micros(), nanos)
    } else {
        format!("Time elapsed: {}ns", d.subsec_nanos())
    }
}

// Password checking
#[derive(Clone)]
enum CheckData {
    ZipCrypto {
        header_enc: Vec<u8>,
        check_byte: u8,
        enc_data: Vec<u8>,
        crc: u32,
        method: u16,
        uncomp_size: u32,
    },
    Aes {
        salt: Vec<u8>,
        verif: [u8; 2],
        ciphertext: Vec<u8>,
        auth: [u8; 10],
        key_len: usize,
    },
}

fn check_password(pwd: &str, data: &CheckData) -> bool {
    match data {
        CheckData::ZipCrypto { header_enc, check_byte, enc_data, crc, method, uncomp_size: _ } => {
            let pwd_bytes = pwd.as_bytes();
            if let Some(mut keys) = crypto::zipcrypto_check(pwd_bytes, header_enc, *check_byte) {
                let plain = crypto::zipcrypto_decrypt(&mut keys, enc_data);
                if *method == 0 {
                    let c = crc32fast::hash(&plain);
                    c == *crc
                } else if *method == 8 {
                    // deflate
                    use flate2::read::DeflateDecoder;
                    use std::io::Read;
                    let mut decoder = DeflateDecoder::new(&plain[..]);
                    let mut out = Vec::new();
                    match decoder.read_to_end(&mut out) {
                        Ok(_) => {
                            let c = crc32fast::hash(&out);
                            c == *crc
                        },
                        Err(_) => false,
                    }
                } else {
                    false
                }
            } else {
                false
            }
        },
        CheckData::Aes { salt, verif, ciphertext, auth, key_len } => {
            let pwd_bytes = pwd.as_bytes();
            let dklen = 2 * key_len + 2;
            let dk = crypto::pbkdf2_hmac_sha1(pwd_bytes, salt, 1000, dklen);
            if dk[dklen-2] != verif[0] || dk[dklen-1] != verif[1] {
                return false;
            }
            let hmac_key = &dk[*key_len..2*(*key_len)];
            let h = crypto::hmac_sha1(hmac_key, ciphertext);
            h[0..10] == auth[..]
        }
    }
}

