    let ml_bits = (data.len() as u64).wrapping_mul(8);
    let mut offset = 0;
    while offset + 64 <= data.len() {
        let mut block = [0u8; 64];
        block.copy_from_slice(&data[offset..offset+64]);
        sha1_compress(&mut h, &block);
        offset += 64;
    }
    let rem = &data[offset..];
    // rem len 0..63
    if rem.len() + 1 + 8 <= 64 {
        // single final block
        let mut block = [0u8; 64];
        block[0..rem.len()].copy_from_slice(rem);
        block[rem.len()] = 0x80;
