        let mut block1 = [0u8; 64];
        block1[0..rem.len()].copy_from_slice(rem);
        block1[rem.len()] = 0x80;
        sha1_compress(&mut h, &block1);
        let mut block2 = [0u8; 64];
        block2[56..64].copy_from_slice(&ml_bits.to_be_bytes());
        sha1_compress(&mut h, &block2);
