use std::sync::OnceLock;
static CRC_TABLE: OnceLock<[u32; 256]> = OnceLock::new();
fn get_crc_table() -> &'static [u32; 256] {
    CRC_TABLE.get_or_init(|| {
        let mut table = [0u32; 256];
        for i in 0..256 {
            let mut c = i as u32;
            for _ in 0..8 {
                if c & 1 != 0 {
                    c = 0xEDB88320 ^ (c >> 1);
                } else {
                    c >>= 1;
                }
            }
            table[i] = c;
        }
        table
    })
}
#[inline(always)]
fn crc32_update(crc: u32, b: u8, table: &[u32; 256]) -> u32 {
    (crc >> 8) ^ table[((crc ^ (b as u32)) & 0xFF) as usize]
}
pub fn zipcrypto_check(password: &[u8], header_enc: &[u8], check_byte: u8) -> Option<[u32; 3]> {
    let table = get_crc_table();
    let mut k0: u32 = 305419896;
    let mut k1: u32 = 591751049;
    let mut k2: u32 = 878082192;
    for &b in password {
        k0 = crc32_update(k0, b, table);
        k1 = k1.wrapping_add(k0 & 0xFF).wrapping_mul(134775813).wrapping_add(1);
        k2 = crc32_update(k2, (k1 >> 24) as u8, table);
    }
    let mut keys = [k0, k1, k2];
    let mut last_plain: u8 = 0;
    for (i, &c) in header_enc.iter().enumerate() {
        let t = (((keys[2] | 2).wrapping_mul((keys[2] | 2) ^ 1) >> 8) & 0xFF) as u8;
        let p = c ^ t;
        keys[0] = crc32_update(keys[0], p, table);
        keys[1] = keys[1].wrapping_add(keys[0] & 0xFF).wrapping_mul(134775813).wrapping_add(1);
        keys[2] = crc32_update(keys[2], (keys[1] >> 24) as u8, table);
        if i == 11 {
            last_plain = p;
        }
    }
    if last_plain != check_byte {
        return None;
    }
    Some(keys)
}
pub fn zipcrypto_decrypt(keys: &mut [u32; 3], data: &[u8]) -> Vec<u8> {
    let table = get_crc_table();
    let mut out = Vec::with_capacity(data.len());
    for &c in data {
        let t = (((keys[2] | 2).wrapping_mul((keys[2] | 2) ^ 1) >> 8) & 0xFF) as u8;
        let p = c ^ t;
        out.push(p);
        keys[0] = crc32_update(keys[0], p, table);
        keys[1] = keys[1].wrapping_add(keys[0] & 0xFF).wrapping_mul(134775813).wrapping_add(1);
        keys[2] = crc32_update(keys[2], (keys[1] >> 24) as u8, table);
    }
    out
}
