pub fn load_zip_file_info(path: &str, file_number: u64) -> Result<ZipFileData, LoadError> {
    let mut f = File::open(path).map_err(|e| LoadError::InvalidArchive(format!("could not open: {}", e)))?;
    let mut data = Vec::new();
    f.read_to_end(&mut data).map_err(|e| LoadError::InvalidArchive(e.to_string()))?;
    if data.len() < 22 {
        // Check if EOCD sig present but truncated? For very small files, original gives Could not find EOCD (as we saw for empty). Good.
        return Err(LoadError::InvalidArchive("Could not find EOCD".to_string()));
    }
    // Find EOCD: search last 66000 bytes from end, starting at len-4 (last possible sig)
    let mut eocd_off: Option<usize> = None;
    let mut truncated_eocd = false;
    let start = if data.len() > 66000 { data.len() - 66000 } else { 0 };
    // Search from len-4 down to start
    let mut i = data.len().checked_sub(4).unwrap();
    loop {
        if data[i] == 0x50 && data[i+1] == 0x4b && data[i+2] == 0x05 && data[i+3] == 0x06 {
            // Found sig, check if enough bytes for EOCD (22)
            if i + 22 > data.len() {
                truncated_eocd = true;
                break;
            }
            // Check comment len
            // Need i+20+2 <= len (since i+22 <= len, i+20+2 == i+22 <= len, ok)
            let comment_len = read_u16_le(&data, i+20) as usize;
            if i + 22 + comment_len == data.len() {
                eocd_off = Some(i);
                break;
            } else if i + 22 + comment_len > data.len() {
                // Comment len would go beyond EOF -> truncated? Could be Unexpected end?
                // For our trunc test (remove 10 bytes), sig at 277, comment_len bytes at 297..298 beyond EOF? Actually i=277, i+20=297 >=289 (len), so read_u16 would panic! Need to check bounds before reading comment_len.
                // We already checked i+22 <= len? For i=277, len=289, i+22=299 >289, so we would have set truncated_eocd above and broken, not reached here. Good.
                // So this branch is for cases where i+22 <= len but comment would exceed? Then it's not valid EOCD, continue searching (maybe earlier sig is real EOCD).
                // Do nothing, continue.
            }
        }
        if i == start { break; }
        if i == 0 { break; }
        i -= 1;
    }
    if truncated_eocd {
        return Err(LoadError::InvalidArchive("Unexpected end of zip::spec::Zip32CDEBlock".to_string()));
    }
    let eocd = match eocd_off {
        Some(o) => o,
        None => {
            return Err(LoadError::InvalidArchive("Could not find EOCD".to_string()));
        }
    };
    // Parse EOCD (we know eocd+22 <= len)
    let total_entries = read_u16_le(&data, eocd+10) as u64;
    let central_size = read_u32_le(&data, eocd+12);
    let central_off = read_u32_le(&data, eocd+16) as usize;
    if central_off >= data.len() {
        return Err(LoadError::InvalidArchive("Invalid CDFH offset in EOCD".to_string()));
    }
    // Additional check for only-EOCD case: central_off + central_size should be <= eocd? For only-EOCD (22 bytes, central_off points to EOCD? Actually EOCD's central_off is from original file (e.g., 81 for 299-len file, but truncated to 22 bytes (last 22), central_off 81 >=22 (len), so >= len, triggers above. Good. Returns Invalid CDFH offset. Good.
    // Parse central directory
    struct CentralEntry {
        flag: u16,
        method: u16,
        mod_time: u16,
        crc: u32,
        comp_size: u32,
        uncomp_size: u32,
        local_off: u32,
        fname: Vec<u8>,
        extra: Vec<u8>,
    }
    let mut entries: Vec<CentralEntry> = Vec::new();
    let mut off = central_off;
    for _ in 0..total_entries {
        if off + 46 > data.len() {
            return Err(LoadError::InvalidArchive("Could not find central directory".to_string()));
        }
        if !(data[off]==0x50 && data[off+1]==0x4b && data[off+2]==0x01 && data[off+3]==0x02) {
            return Err(LoadError::InvalidArchive("Invalid central directory".to_string()));
        }
        let flag = read_u16_le(&data, off+8);
        let method = read_u16_le(&data, off+10);
        let mod_time = read_u16_le(&data, off+12);
        let crc = read_u32_le(&data, off+16);
        let comp_size = read_u32_le(&data, off+20);
        let uncomp_size = read_u32_le(&data, off+24);
        let fname_len = read_u16_le(&data, off+28) as usize;
        let extra_len = read_u16_le(&data, off+30) as usize;
        let comment_len = read_u16_le(&data, off+32) as usize;
        let local_off = read_u32_le(&data, off+42);
        let fname_start = off + 46;
        let fname_end = fname_start + fname_len;
        let extra_end = fname_end + extra_len;
        let end = extra_end + comment_len;
        if end > data.len() {
            return Err(LoadError::InvalidArchive("Invalid central directory".to_string()));
        }
        let fname = data[fname_start..fname_end].to_vec();
        let extra = data[fname_end..extra_end].to_vec();
        entries.push(CentralEntry { flag, method, mod_time, crc, comp_size, uncomp_size, local_off, fname, extra });
        off = end;
    }
    if file_number >= entries.len() as u64 {
        return Err(LoadError::FileNotFound);
    }
    let e = &entries[file_number as usize];
    if (e.flag & 0x01) == 0 {
        let fname_str = String::from_utf8_lossy(&e.fname).to_string();
        return Err(LoadError::NotEncrypted(fname_str));
    }
    let loff = e.local_off as usize;
    if loff + 30 > data.len() {
        return Err(LoadError::InvalidArchive("Invalid local file header".to_string()));
    }
    let local_sig = read_u32_le(&data, loff);
    check_local_sig(local_sig);
    let l_fname_len = read_u16_le(&data, loff+26) as usize;
    let l_extra_len = read_u16_le(&data, loff+28) as usize;
    let data_off = loff + 30 + l_fname_len + l_extra_len;
    let comp_size = e.comp_size as usize;
    if data_off.checked_add(comp_size).map_or(true, |end| end > data.len()) {
        return Err(LoadError::InvalidArchive("Invalid local file header".to_string()));
    }
    let file_data = data[data_off..data_off+comp_size].to_vec();
    let mut aes_extra: Option<AesExtraInfo> = None;
    if e.method == 99 {
        let l_extra_start = loff + 30 + l_fname_len;
        let l_extra = &data[l_extra_start..l_extra_start+l_extra_len];
        let mut found: Option<AesExtraInfo> = None;
        for extra_buf in [l_extra, &e.extra[..]] {
            let mut p = 0;
            while p + 4 <= extra_buf.len() {
                let id = read_u16_le(extra_buf, p);
                let len = read_u16_le(extra_buf, p+2) as usize;
                if p + 4 + len > extra_buf.len() { break; }
                if id == 0x9901 && len >= 7 {
                    let ver = read_u16_le(extra_buf, p+4);
                    let strength = extra_buf[p+8];
                    let real_method = read_u16_le(extra_buf, p+9);
                    found = Some(AesExtraInfo { version: ver, strength, real_method });
                    break;
                }
                p += 4 + len;
            }
            if found.is_some() { break; }
        }
        aes_extra = found;
        if aes_extra.is_none() {
            return Err(LoadError::InvalidArchive("Missing AES extra".to_string()));
        }
    }
    let fname_str = String::from_utf8_lossy(&e.fname).to_string();
    Ok(ZipFileData {
        file_name: fname_str,
        flag: e.flag,
        method: e.method,
        crc: e.crc,
        comp_size: e.comp_size,
        uncomp_size: e.uncomp_size,
        mod_time: e.mod_time,
        aes_extra,
        file_data,
    })
}
